/* The rules behind each section heading, shown in the side panel when a heading is clicked.
   Condensed from the Clockwork Rulebook 2020.1 plus the table's house rules. Items in a topic's body:
   "text" = a paragraph, { h } = a sub-heading, { ul: [...] } = a list, { t: { cols, rows } } = a table,
   { note } = a muted aside (used for the app's own readings of unclear rules). */
const RULES_INFO = {
  attributes: { kicker: "Character basics", title: "Attributes", body: [
    "Seven attributes describe what a character is made of. They run from 0 to 20. Ten is the measure of common folk; below ten an attribute is broken.",
    { t: { cols: ["Attribute", "Covers"], rows: [["Strength", "Brute power: carrying, pushing, lifting, most melee weapons"], ["Dexterity", "Nimbleness and speed: stealth, thievery, accuracy, most ranged weapons"],
      ["Endurance", "Toughness: how much punishment you can take"], ["Mind", "Raw brain power: learning, invention, critical thinking"], ["Willpower", "Mental resolve: resisting the mind and some schools of magic"],
      ["Wisdom", "Knowledge and patience: fitting into places, learned crafts"], ["Presence", "Force of personality: leading, persuading, holding attention"]] } },
    { h: "Rolling them" }, { ul: ["Roll 3d8 for each attribute, set the lowest die aside and add the other two.", "Nothing rolls lower than 6."] },
    { h: "Raising them (house rule)" }, { ul: ["Each level costs its number above ten: 16 → 17 costs 7 Karma.",
      "An attribute that started broken counts from its starting value instead, and tops out ten above it (a starting 6 stops at 16).",
      "Skills can hold one point for each point their attribute has above a true 10."] } ] },

  skills: { kicker: "Character basics", title: "Skills", body: [
    "Clockwork is classless: what a character can do comes from the skills they learn, and there's no limit to how many.",
    { ul: ["Skills run from 0 to 10. Level n costs n Karma, so 0 → 10 costs 55 in all.", "A skill can hold one point for each point its attribute has above 10 (house rule).",
      "Most skills give a 3% modifier per point. Chance skills (Maim, Bash, Cleave, Parry, Pierce, Precision, Evasion, Shield Mastery) give 1% per point."] },
    { h: "Perks" }, "From level 3, each level unlocks a perk. Click a skill's name to see them all; unlocked ones also appear in Skills & Talents.",
    { ul: ["Active ability: a limited-use move, declared before the attack.", "Empowerment: a buff you switch on for a set time, usually paid for afterwards (often in Stamina).", "Passive: always on."] },
    { h: "Durability damage" }, "When an Active ability says durability damage is inflicted, the weapon loses durability by type (one-handed / two-handed):",
    { t: { cols: ["Weapon type", "Durability damage"], rows: [["Slashing", "20 / 30"], ["Piercing", "15 / 30"], ["Bludgeoning", "12 / 20"], ["Ranged", "30 / 40"], ["Limb (a part of you)", "3 HP damage"]] } } ] },

  weaponry: { kicker: "Combat", title: "Weapon skills", body: [
    "Every kind of weapon is its own skill, governed by Strength or Dexterity. One weapon can count under different skills depending on how it's used: a warhammer's spike is Piercing, a thrown longsword Improvised.",
    { t: { cols: ["Level", "Proficiency", "What it gives"], rows: [["0–2", "Inexperienced", "No accuracy bonus"], ["3", "Competent", "Weapon skill + Precision added to accuracy"], ["5", "Proficient", "Durability damage to the weapon is reduced"], ["7", "Adept", "The weapon's Adept property unlocks"], ["10", "Master", "The weapon's Mastery property unlocks"]] } },
    { h: "Weapon types" }, { t: { cols: ["Skill", "Examples"], rows: [["Slashing", "Sword, axe, katana"], ["Piercing", "Spear, dagger, sai"], ["Bludgeoning", "Warhammer, maul, mace"], ["Unarmed", "Fist, feet, knuckleduster"],
      ["Motorized", "Chainsword, powerfist"], ["Improvised", "Broken bottle, table, stool"], ["Finesse", "Rapier, dagger, whip"], ["Rifles", "Arquebus, flintlock"], ["Pistols", "Pepper-box, Peacemaker"], ["Shotguns", "Coach-gun, blunderbuss"],
      ["Sniper Rifles", "Long guns"], ["Explosives", "Bombs and potions"], ["Stringed", "Bow, crossbow"], ["Throwing", "Knives, axes, needles"], ["Heavy", "Machinegun, mortar, minigun"]] } },
    "Costs are the same as skills: level n costs n Karma." ] },

  secondary: { kicker: "Character basics", title: "Secondary skills", body: [
    { ul: ["Three levels, each worth 7%.", "With the attribute below 10 you can learn level 1; below 14, level 2; at 14 or more, all three.",
      "Untrained, with the attribute below 10, you roll with disadvantage. At 10 or above you roll a plain d100."] },
    { h: "Granted by a primary skill" }, { ul: ["Some primary skills grant a secondary one. With only the primary, use that skill's modifier.", "With both, the bonus is 7% per level plus 2 × the primary's points."] },
    "Armor penalties and prosthetics also apply to the matching secondary skills, such as Stealth and Entrada." ] },

  hp: { kicker: "Vitals", title: "Hit points", body: [
    { ul: ["2 HP per point of Endurance (counted 0–20), plus 4 per point of Durability.", "A long rest restores 2 HP, plus Metabolism.", "Exhaustion 7 halves the maximum."] },
    { h: "Dropping to 0" }, "At 0 HP you fall unconscious and are On Death's Door. If the damage left over after reaching 0 equals or beats your HP maximum, you die outright.",
    { h: "Death saves" }, { ul: ["At the start of each of your turns at 0 HP, roll d100. 50 or lower succeeds.", "A failure adds 2 Stamina stacks lost (Exhaustion), which stay even after healing.",
      "Five successes and you're stable; five failures and you die.", "Above 95 counts as two failures. Below 5 stabilises you at once.", "Taking damage at 0 HP is a failure, two from a critical."] },
    { h: "Stabilising" }, "A successful First Aid check stabilises someone On Death's Door. A stable character gains 1 HP." ] },

  blood: { kicker: "Vitals", title: "Blood points", body: [
    "Blood points aren't the body's total blood: they're how much can be lost before death.",
    { ul: ["200 Blood points, plus 20 per point of Bleed Resistance (the app caps this at 400).", "A long rest restores 10, plus 3 per point of Bleed Resistance.",
      "At 100 Blood you lose a Stamina stack, and another for every 20 lost after that (80, 60, 40, 20)."] },
    "Wounds drain Blood every turn in combat, and every minute outside it. See Wounds." ] },

  dp: { kicker: "Vitals", title: "Deprivation", body: [
    { ul: ["4 points per point of Endurance, plus 12 per point of the Deprivation skill.", "A Ration is a meal's worth of food. You can eat 2 per meal.",
      "You lose a Stamina stack at 25, 20, 15, 10 and 5 points.", "At 0 you starve to death."] },
    "Each prosthetic needs one extra ration a day." ] },

  tox: { kicker: "Vitals", title: "Toxicity", body: [
    "Potions and other volatile brews have side effects, counted as Toxicity.",
    { ul: ["Threshold: your Endurance, plus 2 per point of Belly.", "Cleansing dice: 1d6 (the app adds 1d4 for every 2 points of Belly), rolled after each long rest."] },
    { h: "Over the threshold" }, { ul: ["You start puking uncontrollably and lose every potion effect.", "Each turn spent puking cleanses half your cleansing dice and costs a Stamina stack.",
      "You can't generate AP until you're back down to the threshold."] } ] },

  stamina: { kicker: "Vitals", title: "Stamina & Exhaustion", body: [
    "Stamina is physical effort. Each stack lost is a level of Exhaustion, and the effects build up: at 3 you suffer levels 1, 2 and 3.",
    "Stacks are lost to abilities and Empowerments, death saves, blood loss, hunger, puking, extreme heat or cold, long climbs and swims, and heavy loads.",
    { t: { cols: ["Lost", "Effect"], rows: [["1", "The GM can botch your rolls"], ["2", "No reactions"], ["3", "Disadvantage on secondary skill checks and saving throws"], ["4", "Critical fumble chance doubles"],
      ["5", "Disadvantage on ability checks and attack rolls"], ["6", "You can't critically succeed"], ["7", "Hit point maximum halved"], ["8", "No Active abilities or Empowerments"], ["9", "Vital loss rolled on dice takes the maximum"], ["10", "Death"]] } },
    { h: "Botching" }, "Whenever you roll a check, the GM can roll too and make you use their roll: once a round in combat, once every 5 checks outside it.",
    { h: "Getting it back" }, { ul: ["Short rest: 1 stack (2 with Conditioning 6).", "Long rest: 2 stacks (4 with Conditioning 7).", "Stacks from failed death saves stay even after you're healed above 0 HP."] },
    { h: "Conditioning" }, { ul: ["5: the first 2 stacks have no effect; effects start at the 3rd.", "9: Stamina loss can't kill you; each stack past 10 costs 5 HP instead."] },
    { note: "The book's own Stamina table is still to be written. This app reads Stamina loss and Exhaustion as one track, so the Exhaustion table gives each stack's effect." } ] },

  wounds: { kicker: "Vitals", title: "Wounds", body: [
    "A hit hard enough, after armor, opens a wound. Wounds bleed every turn in combat and every minute outside it. You can carry several of the same kind.",
    { t: { cols: ["Wound", "Damage", "Bleeds", "Fix", "Takes", "Needs"], rows: [["Light", "6+", "8", "Dressing", "5 AP", "Bandages"], ["Moderate", "8+", "14", "Stitches", "1 minute", "Medical kit"], ["Mortal", "12+", "20", "Surgery", "1 short rest", "Surgery kit"]] } },
    { ul: ["Treating a wound takes a First Aid or Medicine check and the right kit.", "A wound doesn't bleed while it's being treated. If the treatment fails, each remaining wound bleeds once.", "Durability 7 adds 2 to every damage threshold."] } ] },

  rest: { kicker: "Vitals", title: "Resting", body: [
    { h: "Short rest · about an hour" }, { ul: ["Recover 1 Stamina stack.", "Abilities that recharge on a short rest come back.", "Many skill effects trigger on a short rest."] },
    { h: "Long rest · about eight hours" }, { ul: ["Recover HP and Blood.", "Roll your cleansing dice to clear Toxicity.", "Recover 2 Stamina stacks.", "Every Active ability recharges."] },
    "Sleeping outdoors without a camping kit, a long rest recovers everything except Stamina, and you lose a stack instead." ] },

  load: { kicker: "Gear", title: "Load", body: [
    "Everything carried is counted in small-item slots. Medium items take 2, large 4, huge 8.",
    { ul: ["100 coins, 50 rounds of ammo, 1 ration, 10 stackables (bandages, paper) or 10 m of rope each take one slot. Half stacks round up.",
      "Worn things (a cloak, a backpack) don't count. Armor doesn't count, except heavy armor (large) and plate (huge).",
      "Two weapon sets ride free: two one-handed weapons or one two-handed. Strong Back 3 adds a third. Shields always count as large."] },
    { h: "How much is too much" }, "The tier unit is Strength + 2 × Strong Back. Carry capacity is 3 units.",
    { t: { cols: ["Load up to", "Tier", "Travel", "Defending", "Move"], rows: [["3 units", "Unencumbered", "10 km/h · 40 km a day", "—", "—"], ["4 units", "Lightly", "5 km/h · 20 km", "−10", "−2 m"], ["5 units", "Heavily", "2 km/h · 10 km", "−20", "−4 m"], ["6 units", "Severely", "1 km/h · 5 km", "−40", "−8 m"], ["More", "Over encumbered", "Can't travel", "Can't defend", "—"]] } },
    { note: "The app reads Strong Back 5, 7 and 9 as removing the Lightly, Heavily and Severely penalties." } ] },

  combat: { kicker: "Combat", title: "Turns and AP", body: [
    "Every character gets 5 Action Points (AP) at the start of each turn. Moving, attacking, reloading, defending and most Active abilities cost AP.",
    { h: "Reactions" }, { ul: ["AP you haven't spent when your turn ends stays ready for reactions until your next turn.", "A reaction costs the same AP as the action it is.", "Abilities marked ⟲ by their AP cost can be used as reactions."] },
    { h: "Carrying AP over (Alacrity)" }, { ul: ["Alacrity 8 (Blur): carry up to 1 unspent AP into your next turn, in Medium armor or lighter.", "Alacrity 9 (True Haste): carry up to 1 more.", "Alacrity 10: the True Haste Empowerment makes anything that costs up to 5 AP cost 2."] },
    { h: "Defending" }, { ul: ["Block (Shield Mastery), Parry or Evade: roll d100, take off your bonus; under the attacker's roll, it holds. Encumbrance lowers the bonus.", "Parry and Evade halve the damage, before armor. A critical evade (5% plus 1% per Evasion point) takes it all.", "Parry: melee only (projectiles from Parry 7). Evade: melee only (projectiles and areas from Evasion 7). Block: anything; the shield takes the damage.", "Guard (Parry 4), Slide to the Left (Evasion 4) and Block (Shield Mastery 4) succeed without rolling.", "The book allows one Defend a round unless a perk says otherwise."] },
    { h: "Armor" }, { ul: ["Armor takes the damage first, up to its Armor Value, out of its Soak Pool. The rest goes to your Hit Points.", "At Soak 0 the armor is broken and stops nothing."] },
    { h: "Wounds and death" }, { ul: ["Damage past armor makes a wound: light from 6, moderate from 8, mortal from 12. Wounds bleed at the start of each round.", "At 0 HP you're On Death's Door: a death save each turn (d100, 50 or lower). A failure also costs 2 Stamina. Over 95 is two failures; under 5, you're stable.", "Five successes: stable. Five failures: death. A hit at 0 HP is a failure (two for a critical hit).", "Damage past 0 that's at least your maximum HP kills outright."] },
    { note: "The app's readings: Defend costs 1 AP (Bedo); Parry 8 makes parrying free and Shield Mastery 9 makes blocking free. Halving rounds down. Brace costs 1 AP (0 under Iron-Man) and takes off a number the GM sets, since the book's Actions in Combat chapter isn't written; Durability 4 adds 2 to wound thresholds while braced, Durability 8 halves the damage first and Durability 9 doubles the number. A shield's durability is its soak pool. AP left after a reaction is what Alacrity carries over." },
  ] },
  armor: { kicker: "Gear", title: "Armor", body: [
    { ul: ["Armor Value (AV): taken off every hit.", "Soak pool: each hit drains soak, up to the AV. Damage past the AV goes to HP.", "At 0 soak the armor breaks, and only a skilled craftsman can mend it."] },
    { t: { cols: ["Type", "AV", "Needs", "Penalties"], rows: [["Light", "1–4", "—", "Casting −2×AV"], ["Medium", "5–7", "STR 10", "Stealth −AV, casting −2×AV"], ["Heavy", "8–11", "STR 13, Armor Mastery 3", "Dex skills −AV, Stealth disadv., casting and Entrada −2×AV"], ["Plate", "12–15", "STR 15, Armor Mastery 5", "Dex skills and STR/DEX saves −AV, Stealth disadv., casting −2×AV, travel checks −2×AV"]] } },
    { ul: ["Casting skills are Sangromancy, Warding, Occult: Daemonology, Alchemy and Dreamwalking. Armor Mastery eases their penalty at 5, 7 and 10, and from 4 adds 3 soak per point.",
      "Repairs cost 50 g × AV (light), 70 (medium), 100 (heavy) or 150 (plate) in materials, and an hour per Armor Maintenance attempt.", "Powered armor counts as a machine, not armor."] } ] },

  prosthetics: { kicker: "Gear", title: "Prosthetics", body: [
    "Every prosthetic costs 7% Entrada and 4% Stealth, and its wearer needs one more ration a day.",
    { t: { cols: ["Type", "What it is", "Needs"], rows: [["Basic", "Replaces a lost limb with the same function; anything extra must be worked by hand", "Prosthetic Operation"], ["Expansive", "Adds functions triggered by thought; each use needs a Prosthetic Operation check", "Expansive Prosthetic Operation"], ["Transformative", "Changes shape (spider legs, say), and must keep a human-like resting state; a check on each use", "Transformative Prosthetic Operation"]] } } ] },

  weapons: { kicker: "Gear", title: "Weapons", body: [
    "Every weapon has a flat Damage value, a critical chance, a durability pool and die, and its own Properties and Flaws.",
    { h: "Attacking" }, { ul: ["Roll d100 (the attack roll) and the durability die, and subtract your accuracy.", "A hit deals the weapon's Damage. Under the crit chance (plus your own crit bonus) it's a Critical.",
      "Hit or miss, the weapon loses the durability rolled; a ranged weapon also spends the shot from its clip.", "At 0 durability the weapon gains a Flaw, which a weaponsmith can remove for a fee."] },
    { h: "Melee and ranged" }, { ul: ["Melee weapons reach 2 m.", "Ranged weapons have a clip that costs AP to reload, and may Attack more than once a turn.", "Closer than the optimal range, or past it but inside the maximum, the shot is at disadvantage. Past the maximum it misses."] },
    { h: "Properties" }, { t: { cols: ["Property", "Effect"], rows: [["Defensive (R)", "+R% to parry"], ["Durable (R)", "Loses R less durability"], ["Fast", "May attack first in the round"], ["Finesse", "Can use the Finesse skill"], ["Gore", "Crits on doubles"], ["Impact", "Adds the d10 result as damage"], ["Impale", "Crits on multiples of 10"], ["Penetrating (R)", "Ignores R armor"], ["Reliable (R)", "Deals R damage on a miss"],
      ["Bladebreaker (R) · melee", "Parrying it costs the parrier R% durability"], ["Entangle · melee", "Target is Entangled; Athletics resists"], ["Hack · melee", "Extra damage to armor"], ["Light · melee", "With 1 AP left and no attack taken, deals its damage at round's end"], ["Pummel (R) · melee", "+R% to bash"], ["Reach · melee", "+2 m range"], ["Shield (R) · melee", "+R AV while defending"],
      ["Accurate (R) · ranged", "+R% to attack"], ["Blast (R) · ranged", "Everyone within R m takes half damage and its conditions"], ["Overbearing (R) · ranged", "+R% against a defending target"], ["Pistol · ranged", "No disadvantage in close combat"], ["Precise (R) · ranged", "+R m to both ranges"]] } },
    { h: "Flaws" }, { t: { cols: ["Flaw", "Effect"], rows: [["Brittle (R)", "Loses R more durability"], ["Impotent", "Can never crit"], ["Slow", "Always attacks last; misses if the target moved"], ["Unwieldy", "Every attack at disadvantage"], ["Poorly Weighed · melee", "Misses on doubles"], ["Undamaging · melee", "Armor counts double against it"], ["Inaccurate (R) · ranged", "−R% to attack"], ["Experimental · ranged", "Malfunctions on a high fail; 3 AP to fix"]] } } ] },

  talents: { kicker: "Skills & Talents", title: "Perks and talents", body: [
    "This tab gathers every perk your skills have unlocked, and any talents of your own.",
    { ul: ["Passive: always on.", "Active: limited uses, declared before the attack. Tick a box each time you use one.", "Empowerment: switched on for a number of turns, usually paid for afterwards."] },
    { h: "Reading a perk card" }, { icons: true },
    "Rests recharge spent uses for you: a short rest brings back abilities marked S, a long rest brings back everything.",
    { h: "Talents" }, "Talents are for what the rules don't cover: a runic tattoo, a blessing, a family heirloom's trick. Write what it does and how often; once it's done, the card works like a perk." ] },
  warding: { kicker: "Magic", title: "Warding", body: [
    "Wards are magical effects made by inscribing Sigils. A Ward is a sentence of Words of Power; the effect happens when the last Sigil is inscribed.",
    { h: "Sigils" }, { ul: ["You have a number of Sigils per AP: 3 per point of Warding.", "Say how many AP you use. Available Sigils = AP used × Sigils per AP − Fatigue.", "The Ward costs the sum of its words' Sigils."] },
    { t: { cols: ["Part of the sentence", "Sigils"], rows: [["Subject (I, The Ward, myself, there, the bandit)", "5 (2 at Warding 9)"], ["Adverb (a, an, for, the)", "1 (0 at Warding 9)"], ["Adjective, verb, noun", "Words of Power: their own cost"], ["Conjunction (and, but, when, while)", "10, needs Warding 7"]] } },
    { h: "Ward sentences" }, { ul: ["Every Ward needs a Subject, usually I or The Ward: \"I ignite Fire\", \"The Ward ignites a Fire Column\".", "Be specific: a vague Ward may pass its DC and still do something you didn't want on a high roll.", "The check: d100 minus your modifier, under the GM's DC and the Ward holds. Put the DC in the Difficulty box before you roll, or leave it empty if the GM keeps it secret.", "A word can be a verb and a noun (Ignite / Fire); related concepts can stand in for each other (Fire for heat); two words can make a higher one (Fire + Earth = lava), weaker and dearer than knowing Lava itself."] },
    { h: "Words of Power" }, { ul: ["Your own understanding of a concept: they can't be learned from another warder.", "Learned through Research or Blueprinting; dear at first, cheaper as you study them or find inspiration.", "More specialised words are stronger: Ice beats Cool Water, with a lower cost and DC."] },
    { h: "Fatigue" }, { ul: ["Builds up from difficult Wards or failed attempts; the GM decides how much.", "It all clears after a long rest. Out of combat, each Stamina spent clears 10."] },
    { h: "Kinds of Ward" }, { ul: ["Formulaic (Warding 3): learned from manuals or a teacher, with a set effect, Sigil cost, casting time and materials.", "Ritual (Warding 4): any Ward inscribed slowly, 5 AP's worth of Sigils an hour. Fatigue under 10 becomes 1; over 10 is halved.", "Spontaneous (Warding 5): your own sentences of Words of Power."] },
    { h: "Perks" }, { ul: ["3: Formulaic Wards; Warding only out of combat. 4: Ritual Wards.", "5: Spontaneous Wards. Active (3 uses): 2× Sigils per AP and 2× Fatigue on the next non-Ritual Ward.", "6: repeat an Adjective to amplify it. Active (2 a long rest): no Fatigue on the next non-Ritual Ward.", "7: Conjunctions. Active (3 a long rest): up to 3 Words of Power cost 1 Sigil on the next non-Ritual Ward.", "8: inscribe Wards as reactions. 9: Subjects cost 3 less, Adverbs 1 less."] },
    { note: "The app's readings: Fatigue of exactly 10 on a Ritual is halved (the book says under 10 and over 10); the app's grammar check is a guide (Subject first, a verb somewhere, adjectives lead into a noun), and the GM has the last word on whether a sentence works." } ] },
  alchemy: { kicker: "Magic", title: "Alchemy", body: [
    "Speeding, slowing or reversing natural processes with alchemical circles and life energy: breaking compounds into elements, forming compounds, repairing or moving things as the circle allows.",
    { h: "General rules" }, { ul: ["Alchemy can't create or destroy matter. It changes shape or phase, or rearranges atoms into new compounds. Shape and phase are cheap; changing molecules can be very expensive, even deadly.", "Everything the transmutation needs must be inside the circle. Without proper materials, the circle pulls them from the nearest source, which may be your own blood.", "Each circle does one thing. Two effects need two circles (they can be intertwined, which takes the same time but more skill).", "A damaged or half-drawn circle invites disaster. Stopping a transmutation midway always does, worse the longer its activation."] },
    { t: { cols: ["Circle", "Size", "To draw", "To activate"], rows: [["Fine", "below 15 cm", "2 FA", "1 FA"], ["Diminutive", "15 to 30 cm", "1 BA", "2 FA"], ["Small", "15 cm to 1 m", "1 BA", "4 FA"], ["Medium", "1 to 2 m", "1 A", "1 BA"], ["Large", "2 to 5 m", "2 A to 1 minute", "1 A"], ["Huge", "5 to 10 m", "1 to 5 minutes", "1 A"], ["Gigantic", "10 to 30 m", "5 minutes to 1 hour", "1 minute"], ["Gargantuan", "30 to 100 m", "1 to 4 hours", "5 minutes"], ["Colossal", "above 100 m", "at least 4 hours", "30 minutes"]] } },
    { h: "Energy" }, { ul: ["The energy comes from the alchemist: a transmutation bigger than you can fuel means death by starvation. Know your circle, your goal and your capacity.", "Alchemy 4: draw life energy from nature, (Alchemy ÷ 2)d6. Medium and larger circles eat at least 1 ration whatever you roll.", "Alchemy 10, Empowered (2 AP, 2 Stamina): draw the maximum energy on every attempt, where you can draw it."] },
    { h: "What you can transmute" }, { ul: ["3: pure elements, or what can be separated without a chemical process (mixtures, alloys).", "5: compounds, if you give the reaction enough energy and the materials are there. 7: organic compounds, harder and dearer.", "Never living animals unless truly desperate; human transmutation is taboo and has always ended in disaster."] },
    { h: "Signature Circles and Arrays" }, { ul: ["Alchemy 6: a Signature Circle of your own, Medium or below. Alchemy 9: a second, Large or below.", "Alchemy 8: arrays, circles embedded in a living body for one effect each, for good. Arms, legs and torso: up to 5, Medium or below; 2 limbs and the torso together can hold one Large circle. 50 to 100 hours each; a damaged or severed limb loses its array."] },
    { h: "The signs" }, { t: { cols: ["Sign", "What it stands for"], rows: [
      ["Fire △", "Heat and energy; burning, drying, driving a change on."], ["Water ▽", "Flow and dissolving; cooling, washing, carrying away."],
      ["Air (△ with a bar)", "Breath and movement; vapours, gases, lifting and spreading."], ["Earth (▽ with a bar)", "Solid matter and form; holding, setting, giving weight."],
      ["Quintessence", "The fifth element that binds the other four; balance and wholeness."],
      ["Salt", "The body of a thing; fixing, crystallising, preserving."], ["Sulfur", "The soul of a thing; burning, joining, what makes it act."], ["Mercury", "The spirit of a thing; changing, flowing between states."],
      ["Gold (the Sun)", "Perfection and what lasts; purifying, completing."], ["Silver (the Moon)", "Purity and reflection; clarity, receiving, mirroring."],
      ["Iron (Mars)", "Strength and edges; hardening, cutting, force."], ["Copper (Venus)", "Bonds and attraction; joining, conducting, softening."],
      ["Lead (Saturn)", "Weight and time; slowing, ending, the start of the Great Work."], ["Tin (Jupiter)", "Growth and spreading; expanding, plenty."],
      ["Antimony", "The wild one; cleansing a metal of what doesn't belong."], ["Vitriol", "Acid and breaking down; dissolving to the root."],
      ["The Philosopher's Stone", "The Great Work itself; perfection of the whole."]] } },
    { note: "The signs and their meanings are the old alchemists' (Sun for gold, Moon for silver, and so on). They're there to help you design a circle that fits what it does; the book's rules don't give them effects of their own." },
    { h: "Re-roll (Alchemy 9)" }, { ul: ["After an Alchemy roll and before the result, re-roll once. You lose the most Deprivation possible, and must use the second roll."] },
    { note: "The book doesn't yet say what a Signature Circle changes when you use it; the app keeps them marked in your circle book. The app's circle designer is for drawing your circles; the GM still decides the energy and the difficulty of each transmutation." },
  ] },
  dreamwalking: { kicker: "Magic", title: "Dreamwalking", body: [
    "Walking the dream realm, and bending it: moving yourself (Transposition), moving things (Translocation) and changing them (Transfiguration).",
    { h: "Toll and Calamity" }, { ul: ["Toll is the pressure of everything you sustain. Each manipulation adds to it.", "Dreamwalking bonus = your modifier − your Toll.", "Calamity chance = 5% + your Toll. The GM rolls it when a translocation or transfiguration fails or targets a sentient being, when a translocation target is over 3 times what you can lift, when you're damaged with a Toll over 30, or when you lose concentration on a transfiguration.", "Tolls disperse when you release the manipulation, or at a long rest."] },
    { h: "Entering the dream realm" }, { ul: ["Dreamwalking 3: asleep, roll a Dreamwalking check (the GM sets the difficulty). On a failure you just sleep; on a very bad one you arrive with a Calamity.", "Dreamwalking 6: no check while asleep. You can also dream during a mundane task (walking, riding): +15% Toll for the visit.", "Dreamwalking 8: take willing travellers within 20 m and in sight: +8% Toll each for the visit."] },
    { h: "Manipulations" }, { ul: ["Transposition (4): travel to a place you can see or have seen, with what you carry. Not teleportation: you hit what's in the way, and you land near the spot.", "Translocation (5): touch a thing to move it by will. 1 AP to start (2 if you can't lift it); moving it up to your movement costs 2 AP; under 1 kg you can throw it (2 AP); cancelling is free. It must be under 3 times what you can lift. The GM sets the difficulty and the Toll.", "Transfiguration (7): change a whole object into something you know the exact make-up of, from 1 AP to minutes. It reverts when you let go, so think about what that means. The GM sets the difficulty, time and Toll.", "Sentient targets roll Willpower against your Dreamwalking check."] },
    { h: "The dream realm's vault (Dreamwalking 5)" }, { ul: ["Active, 1 AP: send an inanimate object you're touching and can lift into the dream realm (3 minutes' concentration and a check). On a failure it's lost until your next long rest.", "Each item adds Toll by its size. Renew the binding each day with a successful check, or everything comes back."] },
    { note: "Weapons and armor are inanimate objects you can lift, so they can go into the vault too. A worn suit is taken off first, and both come back to Gear. The GM sets the Toll by size." },
    { h: "Dreamspheres (Dreamwalking 7)" }, { ul: ["Active (2 AP, 1 from Dreamwalking 9; 3 uses a long rest): a 20 m sphere of the dream realm in the waking world, for 3 turns. You must be inside it to create it and to use manipulations.", "+2 m radius for +4% Toll, chosen when you create it. Keep it open past 3 turns with a successful check each round: +5% Toll per extra turn.", "Dreamwalking 9: delay the creation by up to a minute after you declare it."] },
    { note: "In the app you can drag the sphere anywhere in the scene (or move it with the arrow keys) to show where it stands." },
    { h: "Dreamseeds (Dreamwalking 10)" }, { ul: ["A palm-sized object holding a piece of the dream realm: it can be manipulated in the waking world, and spheres can be seeded on it.", "Two are free; each one past that adds 15% Toll until it's destroyed. Remaking a destroyed seed is a 4-hour ritual in the dream realm with materials worth 10000 rubles."] },
    { h: "Perks" }, { ul: ["6, Active (1 AP, 2 uses a long rest): your next Perception, Insight or Investigation roll has advantage; +5% Toll until a long rest."] },
    { note: "The app's readings: every Toll disperses at a long rest, including the Toll of items left in the dream realm (the items stay); dreamseeds keep theirs until destroyed. The app adds up the Toll from what you record; the GM sets each manipulation's Toll." },
  ] },
  demonology: { kicker: "Magic", title: "Occult: Daemonology", body: [
    "Summoning otherworldly beings called daemons, and forming contracts to control them.",
    { h: "Contracts" }, { ul: ["From Demonology 3 you can summon daemons and form contracts with them.", "What each contract asks for depends on the daemon. Once it's formed, you can summon that daemon to the prime plane."] },
    { h: "Summoning" }, { ul: ["Summoning costs 2 AP and dismissing costs 1 AP (1 and 0 from Demonology 7).", "Only one daemon can be summoned at a time.", "Summons a day: 1 per 2 points of Demonology.", "A daemon can stay half an hour per point of Demonology."] },
    { h: "Perks" }, { ul: ["4, Active (2 uses a long rest, 1 AP and the ability's cost): partial summon. Use one of a daemon's abilities with a Demonology check, without summoning it; it can't be damaged. Only for abilities that take effect in a single turn. The difficulty depends on the ability.",
      "5, Active (2 uses a long rest, 3 AP): boost one of your daemon's abilities with a Demonology check. The boost and the difficulty depend on the ability.",
      "6: partial summons as often as you like, for a material cost that depends on the ability.",
      "7, Active (1 use a long rest, 3 AP): banish a daemon to its realm. Roll Demonology against its Willpower; on a failure it can't be banished for 24 hours.",
      "7: summoning and dismissing cost 1 AP less. You get 2 more AP each turn, only for your daemons' innate abilities.",
      "8: boosts as often as you like, for a material cost that depends on the ability.",
      "9: name a Guardian daemon. It isn't bound by the summon duration and can stay with you, beside your normal summons.",
      "10, Empowered (5 AP, 3 Stamina, 3 turns): summon up to 5 contracted daemons at once. These don't count towards your daily summons."] },
    { note: "The app's readings: the book counts summons \"a day\"; the app renews them at each long rest. Checks are rolled like the other schools (d100 minus your modifier, under the GM's difficulty); for banishing, the app shows your roll beside the daemon's Willpower and the GM decides." },
  ] },
  harmony: { kicker: "Magic", title: "Occult: Harmony", body: [
    "Controlling the flow of your body's spiritual energy through its chakras, each reinforced with a harmonic element.",
    { h: "Chakras" }, { ul: ["One more chakra opens at each level from 3 to 10: Opening, Life, Pain, Healing, Limit, Wonder, View, Death.", "Each chakra holds one element at a time and gives that element's power from its table.", "You can only reinforce a chakra with an element you know."] },
    { h: "Harmonic elements" }, { ul: ["You learn one element at Harmony 3, and one more at 5, 7 and 10.", "The choice is permanent."] },
    { h: "Changing reinforcements" }, { ul: ["One chakra over a short rest, or all of them over a long rest. Changes made over a long rest count as made before it.", "Harmony 5, Active (2 AP, 3 uses a long rest): change one chakra.", "Harmony 10, Empowered (2 Stamina, 1 minute of meditation): change all of them."] },
    { h: "Harmonic Affinity" }, { ul: ["Each element you know has its own Affinity: the number of chakras it reinforces, plus your Aether Affinity.", "Many chakra powers grow with it, and some start at Affinity 4 or 6."] },
    { h: "Releasing chakras (Harmony 7)" }, { ul: ["Release any chakra at any time, for 0 AP each. Each released chakra adds 1 Aether Affinity, which raises every other Affinity too.", "They stay released for as many turns as you have points in Harmony, counted from the first. You can keep them open after that with Harmony checks against ever harder DCs.", "When they close you lose 1 Stamina per released chakra. This can kill you.", "View, released: temporary hit points equal to your maximum, only against the damage types it resists. Death, released: every reinforcement effect for 2 turns."] },
    { note: "The book's Harmonic Elements table is still blank (TBD); the app uses the five elements its chakra tables list: Fire, Earth, Wind, Water, Spirit. The Wonder chakra's powers and the Limit and Wonder release effects aren't written yet. Where the book halves an Affinity, the app rounds down; the book doesn't say." },
  ] },
  powdertinkering: { kicker: "Crafting", title: "Powdertinkering", body: [
    "Custom ammunition, explosives and weapon oils, built one part at a time. You need a Powdertinker kit.",
    { h: "Each part is one roll" }, { ul: ["Modifier = 3% × Powdertinker, plus any item bonus.", "Roll d100 and subtract the modifier. Under the part's difficulty, it holds.", "Each attempt uses 200 g: container materials for Coats, Tips and Areas; element solution for Cores and Status."] },
    { t: { cols: ["Part", "Difficulty", "Rating"], rows: [["Coat (always first)", "60%", "—"], ["Tip (several)", "40%, −5% per step above base", "Powdertinker"], ["Area (one)", "30%", "Powdertinker"], ["Core (one element)", "40%, −10% per step above base", "Powdertinker ÷ 2"], ["Status (match the Core)", "40%", "Powdertinker ÷ 2"]] } },
    { h: "Failures" }, { ul: ["A failed roll loses its materials and gives the batch a Detriment (the GM decides what). You may try the same part again.", "Powdertinker 3 lets you fail once; Powdertinker 6, twice. One more scraps the batch and everything in it."] },
    { h: "Saved recipes" }, { ul: ["After a craft, name it and click \"Save recipe\". It appears under Saved recipes above the munitions.", "One click on a saved recipe puts every part back: the munition, coat, tips, area, core and statuses.", "Ammo made from a saved recipe, with every part holding, goes into the inventory under its name. Change any part and it's a new recipe again.", "Saving under a name that already exists updates that recipe; × deletes one."] },
    { h: "Your own parts" }, { ul: ["Each part has \"+ A custom …\" under the book's choices: give it a name, what it does and its difficulty.", "A custom Tip can have a Rating (each +1 makes it 5% harder); a custom Core is a new element with its own solution under Supplies (each +1 makes it 10% harder); a custom Status belongs to one element.", "They're saved on this character and marked \"custom\". The × removes one (a removed Core takes its Statuses with it).", "What a custom part does in play is up to the GM, like a Detriment."] },
    { h: "Unlocks" }, { ul: ["3: proficient, custom Coats.", "4: Tips and Cores.", "5: keep a failed property as well as its Detriment (once per long rest).", "7: Area and Status.", "8: half a batch more per unused failure.", "9: a whole batch more.", "10: ignore one Detriment (once per long rest)."] },
    { note: "The app's readings: the Component Access table (which munition takes which part) is garbled in our copy of the book and is our best guess; bombs keep a free Sphere; grenades and oils roll their base layer at 60%; both perk abilities are once per long rest." } ] },
  armorRepair: { kicker: "Crafting", title: "Repairing armor", body: [
    "Armor Maintenance 3 lets you mend a suit's Soak Pool. You need a blacksmithing kit; heavy and plate armor also need a forge.",
    { t: { cols: ["Type", "Materials per attempt", "Repair Die"], rows: [["Light", "50 g × AV", "d6"], ["Medium", "70 g × AV", "d8"], ["Heavy", "100 g × AV", "d10"], ["Plate", "150 g × AV", "d12"]] } },
    { h: "How a repair goes" }, { ul: ["Roll an Armor Maintenance check: d100 minus your modifier (3% × Armor Maintenance).", "Repair Count = 10 − check ÷ 10, rounded down. A check of 32 gives 6.", "Roll the Repair Die that many times. The total goes back into the Soak Pool.", "Each attempt takes an hour."] },
    { h: "Working for other players" }, { ul: ["On the Gear tab, a player clicks \"Send for repair\" under a weapon or suit and picks a smith in the same campaign (Maintenance 3 or more) or the town smith. The item stays in their Gear but can't be used (or worn) until it's back.", "The town smith is an NPC the GM runs: the GM sees the item on the GM table, decides how much is repaired and sends it back. The payment stays with the NPC.", "They can add a payment: coins, something from their inventory, and a note. Coins and items leave their sheet at once; the smith gets them when the repair is done, and they come back if the item is sent back or taken back.", "The smith gets a notice (only while the smith's character is open), then sees only that item, under \"Jobs from other players\" on the Repair bench, and repairs it with their own roll and materials, as many times as it takes (\"Repair again\"). \"Send it back\" returns it with every repair; before any repair, \"Send back unrepaired\" returns it as it was.", "The result lands on the owner's item the next time the owner's app is open.", "On the Craft bench, \"Made for\" sends a finished piece straight to another player's Gear (same campaign only)."] },
    { note: "The app's readings: the Repair Count never goes above 10 dice (Utku). A suit repaired for someone else fills up to its wearer's own Soak maximum. A broken suit (Soak 0) needs a skilled craftsman; the app counts Armor Maintenance 5 as skilled and charges double materials to rebuild it. This last one is a draft to confirm." } ] },
  armorCraft: { kicker: "Crafting", title: "Crafting armor", body: [
    "Armor Maintenance 4 lets you make mundane suits; 8 adds Artisan properties. The 2020.1 book names armor crafting but doesn't give its steps yet, so the app follows the book's weapon crafting.",
    { h: "How a craft goes (our reading)" }, { ul: ["The GM gives the suit's type, Armor Value and Soak Pool.", "Materials: 5 × the suit's repair cost, of its type.", "Difficulty 70%. Roll d100 minus your modifier; under 70, the suit is made.", "A failure gives the suit a flaw (the GM decides it) and you roll again. A second failure loses the suit and every material.", "Crafting takes 8 hours. Heavy and plate need a forge."] },
    { h: "Extras (our reading)" }, { t: { cols: ["Extra", "Difficulty"], rows: [["Armor Value +1 (within the type's range)", "−10%"], ["Soak Pool +5", "−5%"]] } },
    { note: "Changed from weapon crafting: the stat extras use armor's two numbers in place of the weapon table; the 'two random positive properties' step is left out because armor has no property list; a new suit's Soak Pool defaults to 10 × AV, from the book's chain-mail example. The base Armor Value and Soak Pool come from the GM, so on a table only a GM can set them; players raise them with the extras (Utku). Artisan properties (level 8) aren't written in the book yet." } ] },
  weaponRepair: { kicker: "Crafting", title: "Repairing weapons", body: [
    "Weapon Maintenance 3 lets you craft, repair and salvage mundane weapons. You need a blacksmithing kit or a forge.",
    { t: { cols: ["Weapon", "Materials per attempt"], rows: [["One-handed", "400 g"], ["Two-handed", "800 g"], ["Unwieldy", "+400 g"]] } },
    { h: "How a repair goes" }, { ul: ["Roll a Weapon Maintenance check: d100 minus your modifier (3% × Weapon Maintenance).", "Repair Count = 10 − check ÷ 10, rounded down. A check of 32 gives 6.", "Roll a d10 that many times. The total goes back into the weapon's Durability.", "Each attempt takes an hour."] },
    { h: "Working for other players" }, { ul: ["On the Gear tab, a player clicks \"Send for repair\" under a weapon or suit and picks a smith in the same campaign (Maintenance 3 or more) or the town smith. The item stays in their Gear but can't be used (or worn) until it's back.", "The town smith is an NPC the GM runs: the GM sees the item on the GM table, decides how much is repaired and sends it back. The payment stays with the NPC.", "They can add a payment: coins, something from their inventory, and a note. Coins and items leave their sheet at once; the smith gets them when the repair is done, and they come back if the item is sent back or taken back.", "The smith gets a notice (only while the smith's character is open), then sees only that item, under \"Jobs from other players\" on the Repair bench, and repairs it with their own roll and materials, as many times as it takes (\"Repair again\"). \"Send it back\" returns it with every repair; before any repair, \"Send back unrepaired\" returns it as it was.", "The result lands on the owner's item the next time the owner's app is open.", "On the Craft bench, \"Made for\" sends a finished piece straight to another player's Gear (same campaign only)."] },
    { note: "The app's readings: the Repair Count never goes above 10 dice, as for armor (Utku). A weapon at 0 durability can be repaired like any other; the flaw it gained for breaking stays until a weaponsmith removes it." } ] },
  weaponCraft: { kicker: "Crafting", title: "Crafting weapons", body: [
    "Weapon Maintenance 3 lets you craft mundane weapons; 5 adds exotic materials; 7 a second chosen property and one more failure.",
    { h: "How a craft goes" }, { ul: ["Ask the GM for the weapon's base stats: damage, accuracy, critical chance, durability and durability die.", "Materials: 5 × the weapon's repair materials.", "Difficulty 70%, made harder by any changes you add (below). Roll d100 minus your modifier; under the difficulty, it's made.", "If it has fewer than 2 properties, it gains 2 random positive ones.", "A failure gives the weapon a random flaw and you roll again. A second failure (third from Weapon Maintenance 7) loses the weapon and every material.", "Crafting takes 8 hours."] },
    { h: "Changes you can add" }, { t: { cols: ["Change", "Difficulty"], rows: [["Damage +1", "−10%"], ["Accuracy +1%", "−2%"], ["Critical chance +1%", "−2%"], ["A weapon property", "−10%"], ["Durability +1", "−1%"], ["Higher durability die", "−5%"]] } },
    "Exotic materials (unusual metals, monster parts) change the difficulty either way, as the GM says, and all their properties go onto the weapon.",
    { note: "The app's readings: the random properties and flaws are drawn from those that fit the weapon (melee or ranged), and the GM sets any Rating. A ranged weapon's clip and ranges are set afterwards on its card. Base stats come from the GM, so on a table only a GM can set them on the bench; players raise them with the changes above (Utku). Tuning, Runecarving and Masterworking aren't on the bench yet." } ] },
  brewing: { kicker: "Crafting", title: "Brewing", body: [
    "Brewing 3 lets you brew potions. You need a brewing kit, herbs or monster parts (the GM tells you their effects), and a flask.",
    { h: "How a brew goes" }, { ul: ["Your modifier is 3% × Brewing, plus any item bonus.", "Roll d100 and subtract your modifier. Under the brew's difficulty, it holds; otherwise the materials are lost.", "On a success, roll its toxicity and write the brew's stats down.", "A brew takes an hour."] },
    { h: "Recipes" }, "Each recipe has a base cost in herbs, a base effect, a toxicity die and a difficulty, plus the same per increment (Brewing 5). The GM can give you new ones.",
    { t: { cols: ["Recipe", "Effect", "Herbs", "Toxicity", "Difficulty"], rows: [["Health Potion", "2×Brewing HP, +2 per increment", "300 g + 100", "1d8 + 1d4", "50%, −(15 − Brewing)%"], ["Skele-Gro", "Bones heal 3× faster, +1×", "400 g + 150", "1d12 + 1d8", "50%, −(13 − Brewing)%"], ["The Sanguinar", "10×Brewing blood, +3×Brewing", "300 g + 200", "1d10 + 1d4", "40%, −(13 − Brewing)%"], ["Sleep Tightener", "1 Exhaustion point, +1", "500 g + 500", "1d8 + 1d6", "30%, −(18 − Brewing)%"], ["The Pick Me Up", "Brewing÷3 turns, +1", "200 g + 100", "1d6 + 1d4", "50%, −(13 − Brewing)%"]] } },
    { h: "Catalysts (Brewing 5)" }, { ul: ["Declare one before the roll; its difficulty is added to the brew's.", "You know 1 catalyst per 3 levels of Brewing (4 at 10).", "Duration: doubles a brew lasting under an hour; toxicity ×2.", "Toxicity: lowers toxicity by your Brewing.", "Volatile: a d100 decides: 1–10 five more increments, 11–25 three, 26–70 nothing, 71–94 it turns inert, 95–100 it explodes for 1d20 in 2 m."] },
    { h: "Potent Brews (Brewing 7)" }, { ul: ["One flask with two effects (the same effect may be taken twice). Roll for both; if either fails, both fail.", "Takes twice as long.", "Brewing 9: toxicity takes the higher of the two rolls instead of both, and increments apply to both."] },
    { note: "The app's readings: the book writes per-increment difficulty as \"%15 − SP\"; the app reads it as 15% minus your Brewing (never below 0) per increment. A catalyst's \"−%10 + SP\" is read the same way: 10% harder, less your Brewing. Catalysts start at Brewing 5 with at least one known. The level 6 perk (\"extra materials to make brewing easier\") points to an \"Incrementing Brews\" section that's missing from our copy of the book, so it isn't on the bench yet. Flasks aren't counted. A catalyst the GM gives you takes your Brewing off its difficulty like the book's, and counts towards the catalysts you know. The book has no batches (one brew, one flask): \"Brew the same again\" just repeats the brew with a new roll." } ] },
  hunting: { kicker: "Crafting", title: "Hunting", body: [
    "Trophies are parts carved from slain monsters. Hung on your belt and attuned, they lend you their properties: positive ones help, negative ones hinder, void ones do nothing. Your modifier is 3% × Hunting.",
    { h: "Using trophies" }, { ul: ["3: you can use (attune) trophies up to level 1, and one more level per point from Hunting 4 (level 5 at Hunting 7).", "Only a trophy on your belt can be attuned. You attune one at a time.", "5, Release (1 AP, 1 Stamina, 3 turns): an attuned trophy on your belt has its numbers doubled.", "6, a second attunement (1 AP, 1 Stamina, 3 turns): attune one more belted trophy while the first stays attuned.", "9: these can be used together, and each costs 1 AP less."] },
    { note: "The book doesn't say how many trophies a belt holds. The app gives it 4 loops; change the number to whatever your GM says." },
    { h: "Carving (salvaging, Hunting 4)" }, { ul: ["The GM tells you the trophy's level. A trophy of level L has 2 × L properties (level 3: six).", "Roll d100 and subtract your modifier, then read the table below.", "A trophy can't be all positive: if the table gives as many positives as it has properties, one is left over.", "Every property the table doesn't decide is rolled again, one at a time."] },
    { t: { cols: ["d100 − modifier", "The trophy"], rows: [["81 or more", "No trophy"], ["71 to 80", "All negative"], ["61 to 70", "2 negative"], ["51 to 60", "1 negative"], ["31 to 50", "1 positive"], ["21 to 30", "2 positive"], ["11 to 20", "3 positive"], ["1 to 10", "4 positive"], ["−9 to 0", "5 positive"], ["−19 to −10", "6 positive"], ["−29 to −20", "7 positive"], ["−30 or less", "8 positive"]] } },
    { note: "For the properties rolled one at a time, the app reads 51 or more (the table's negative rows) as negative, and anything lower as void. The book's example (a 62 made one negative) fits this, but the book doesn't spell it out." },
    "Then ask the GM for the trophy card and write each property down.",
    { h: "Merging (combining, Hunting 7)" }, { ul: ["A giver trophy passes its positive properties to a receiver. Roll d100 minus your modifier and read the table below. The giver burns.", "8: once per giver you may ignore the roll and try again. This triples the cost of the combination.", "The cost is the GM's to set."] },
    { t: { cols: ["d100 − modifier", "Positive properties passed"], rows: [["80 or more", "None: it fails"], ["Below 80", "0"], ["Below 60", "1"], ["Below 50", "2"], ["Below 30", "3"], ["Below 20", "4"], ["Below 10", "5"], ["Below 0", "6"], ["Below −10", "7"], ["Below −20", "8"], ["Below −30", "9"]] } },
    { note: "The book doesn't say where passed properties go on the receiver. The app puts each one in place of a void property, then of a negative one, and adds it if there's neither. The app also burns the giver on a failure." },
    { h: "Other perks" }, { ul: ["3: you know a mythology (one more per point after that). Lore checks about it use your Hunting modifier.", "7: you're a renowned hunter with a title from the GM.", "10: creatures you set out to kill must save against your fear, and with an active trophy against one you gain a Legendary Action each round."] },
  ] },
  runecrafting: { kicker: "Crafting", title: "Runecrafting", body: [
    "A runestone is a gem (or certain monster parts) enchanted in a ritual that consumes materials. You need a runecrafting kit, the gem and the materials. An Appraisal check tells you what a gem can become and what the materials cost.",
    { h: "Two kinds of stone" }, { ul: ["Enhancing: raises one of the user's skills, attributes or abilities. Its strength (potency) comes from the table below.", "Manifesting: has an effect it can produce, all the time or a number of times. The GM sets a difficulty for it."] },
    { h: "How to enchant" }, { ul: ["Your modifier is 3% × Runecrafting, plus any item bonus.", "Roll d100 and subtract your modifier.", "Enhancing: look the result up below, then roll the potency die. Manifesting: under the GM's difficulty, it holds.", "On a failure the materials are lost.", "An enchantment takes 8 hours. Write the stone down."] },
    { t: { cols: ["d100 − modifier", "Potency"], rows: [["Below −30", "12"], ["−30 to −21", "d12"], ["−20 to −11", "d10"], ["−10 to −1", "d8"], ["0 to 9", "d6"], ["10 to 19", "d4"], ["20 to 29", "1"], ["30 or more", "Failure"]] } },
    "Semi-precious gems hold at most d6 (a better roll counts as d6) and only one power.",
    { h: "Perks" }, { ul: ["3: identify the enchantments on runestones you find (an hour).", "4: enchant semi-precious gems.", "5: precious gems too; spend extra materials for +1% per 50 rubles (not for Hoaxstones).", "6: Hoaxstones.", "7: Potent Runestones: two effects (the same one twice stacks), twice the time.", "8: once per gemstone, roll the check again; the materials are lost and must be paid again, and the second roll stands.", "9: extract runes without ruining the item or the rune.", "10: move enchantments between runestones; merge two runestones into a Potent Runestone."] },
    { h: "Potent Runestones (7)" }, "Made like two runestones at once. If either roll fails, both effects, the gem and the materials are destroyed.",
    { h: "Hoaxstones (6)" }, { ul: ["A mundane object becomes a temporary runestone, made like any other.", "Instead of materials, pay life force: for each 100 rubles the materials are worth, 2 hit points, 10 blood points or 5 deprivation points, all from one source.", "It lasts 1 hour, then crumbles. Each extra hour costs the same again, chosen when you make it.", "If the check fails, the life force is still lost."] },
    { h: "Embedding and removing" }, "Enhancing stones and stronger manifesting stones must be set into an item with a runeslot. Removing one usually destroys either the item or the stone: you choose which to save.",
    { note: "The app's readings: \"Above 30\" on the table is read as 30 or more failing (so 29 is the last success). Potent Runestones need a precious gem, since a semi-precious one holds a single power. A Hoaxstone's life force is counted per started 100 rubles (250 rubles is 3 × the cost), and the stone itself still takes 8 hours to make, as the book says it is made like any other. Semi-precious caps and extra materials don't apply to Hoaxstones; the gem list's precious/semi-precious split (ruby, sapphire, emerald, diamond are precious) is the usual one, not the book's. The level 8 re-roll is offered right after a check you don't like, once per gemstone, and isn't offered for Hoaxstones. Identifying, extracting, moving and merging are listed but have no roll in the book, so the bench doesn't do them. The book has no batches (one ritual, one stone): \"Enchant another the same way\" repeats the ritual with a new roll and new materials. Saved effects only fill in the effect; their difficulty is the GM's." } ] }
};
